import { workflow, trigger, node, expr, ifElse, sticky } from '@n8n/workflow-sdk';

const webhookTrigger = trigger({
	type: 'n8n-nodes-base.webhook',
	version: 2.1,
	config: {
		name: 'Webhook',
		parameters: {
			httpMethod: 'POST',
			path: '9cdcd623-305c-4da3-877d-3c9b7a05bd0a',
			responseMode: 'responseNode',
			options: {},
		},
		position: [0, 0],
	},
	output: [
		{
			body: {
				METHOD: 'crm.contact.list',
				PARAMS: { filter: { EMAIL: 'x@y.ru' }, select: ['ID'], start: '-1' },
			},
			headers: {},
		},
	],
});

const prepareJs =
	'function headerGet(headers, name) {\n' +
	"  if (!headers || typeof headers !== 'object') return undefined;\n" +
	'  const n = String(name).toLowerCase();\n' +
	'  for (const k of Object.keys(headers)) {\n' +
	'    if (String(k).toLowerCase() === n) return headers[k];\n' +
	'  }\n' +
	'  return undefined;\n' +
	'}\n' +
	'function flatten(obj, prefix) {\n' +
	'  const pairs = [];\n' +
	'  if (obj === null || obj === undefined) return pairs;\n' +
	"  const p = prefix || '';\n" +
	"  if (typeof obj !== 'object') {\n" +
	'    pairs.push([p, obj]);\n' +
	'    return pairs;\n' +
	'  }\n' +
	'  if (Array.isArray(obj)) {\n' +
	'    for (let i = 0; i < obj.length; i++) {\n' +
	"      const key = p ? p + '[' + i + ']' : '[' + i + ']';\n" +
	'      pairs.push(...flatten(obj[i], key));\n' +
	'    }\n' +
	'    return pairs;\n' +
	'  }\n' +
	'  for (const key of Object.keys(obj)) {\n' +
	"    const next = p ? p + '[' + key + ']' : key;\n" +
	'    pairs.push(...flatten(obj[key], next));\n' +
	'  }\n' +
	'  return pairs;\n' +
	'}\n' +
	"const inboundSecret = process.env.EKLEKTIKA_N8N_INBOUND_SECRET || '';\n" +
	"const b24prefix = process.env.EKLEKTIKA_B24_REST_PREFIX || '';\n" +
	'const item = $input.first().json;\n' +
	"const payload = item.body && typeof item.body === 'object' ? item.body : item;\n" +
	'const method = payload.METHOD || payload.method;\n' +
	'const params = payload.PARAMS || payload.params || {};\n' +
	"const hdrSecret = headerGet(item.headers, 'x-eklektika-site-n8n-secret');\n" +
	"if (inboundSecret && String(hdrSecret || '') !== String(inboundSecret)) {\n" +
	"  return [{ json: { siteOut: { success: 0, error: 'unauthorized' } } }];\n" +
	'}\n' +
	'if (!b24prefix || !method) {\n' +
	'  return [{\n' +
	'    json: {\n' +
	'      siteOut: {\n' +
	"        success: 0, error: 'config',\n" +
	"        message: 'EKLEKTIKA_B24_REST_PREFIX or METHOD missing',\n" +
	'      },\n' +
	'    },\n' +
	'  }];\n' +
	'}\n' +
	'let root = String(b24prefix);\n' +
	"while (root.endsWith('/')) root = root.slice(0, -1);\n" +
	'let m = String(method);\n' +
	"while (m.startsWith('/')) m = m.slice(1);\n" +
	"const url = root + '/' + m + '.json';\n" +
	'const pairs = flatten(params);\n' +
	"const delim = String.fromCharCode(38);\n" +
	'let httpBody = \'\';\n' +
	'for (let i = 0; i < pairs.length; i++) {\n' +
	'  const kv = pairs[i];\n' +
	"  const part = encodeURIComponent(kv[0]) + '=' + encodeURIComponent(kv[1] === null || kv[1] === undefined ? '' : String(kv[1]));\n" +
	'  httpBody = i === 0 ? part : httpBody + delim + part;\n' +
	'}\n' +
	'return [{ json: { url: url, httpBody: httpBody } }];';

const prepareCode = node({
	type: 'n8n-nodes-base.code',
	version: 2,
	config: {
		name: 'Build Bitrix REST URL + body',
		parameters: {
			mode: 'runOnceForAllItems',
			language: 'javaScript',
			jsCode: prepareJs,
		},
		position: [240, 0],
	},
	output: [{ json: { url: 'https://example.bitrix24.ru/rest/1/x/crm.contact.list.json', httpBody: 'start=-1' } }],
});

const gate = ifElse({
	version: 2.2,
	config: {
		name: 'Ready to call Bitrix24?',
		parameters: {
			conditions: {
				combinator: 'and',
				options: {
					version: 2,
					caseSensitive: true,
					leftValue: '',
					typeValidation: 'strict',
				},
				conditions: [
					{
						id: 'has-url',
						leftValue: '={{ $json.url }}',
						rightValue: '',
						operator: { type: 'string', operation: 'notEmpty' },
					},
				],
			},
		},
		position: [480, 0],
	},
});

const postBitrixJs =
	'const item = $input.first().json;\n' +
	'const url = item.url;\n' +
	'const httpBody = item.httpBody;\n' +
	'let raw;\n' +
	'try {\n' +
	'  raw = await this.helpers.httpRequest({\n' +
	"    method: 'POST',\n" +
	'    url,\n' +
	'    headers: {\n' +
	"      'content-type': 'application/x-www-form-urlencoded; charset=UTF-8',\n" +
	"      accept: 'application/json',\n" +
	'    },\n' +
	'    body: httpBody,\n' +
	'  });\n' +
	'} catch (e) {\n' +
	"  return [{ json: { error: 'n8n_http_error', error_description: e.message || String(e) } }];\n" +
	'}\n' +
	'return [{ json: raw }];';

const postBitrix = node({
	type: 'n8n-nodes-base.code',
	version: 2,
	config: {
		name: 'POST Bitrix24 CRM REST',
		parameters: {
			mode: 'runOnceForAllItems',
			language: 'javaScript',
			jsCode: postBitrixJs,
		},
		position: [720, -140],
	},
	output: [{ result: {}, error: undefined }],
});

const mapOkJs =
	'let b24 = $input.first().json;\n' +
	"if (typeof b24 === 'string') {\n" +
	'  try {\n' +
	'    b24 = JSON.parse(b24);\n' +
	'  } catch (parseErr) {\n' +
	"    return [{ json: { success: 0, error: 'invalid_b24_json', snippet: String(b24).slice(0, 500) } }];\n" +
	'  }\n' +
	'}\n' +
	"if (b24 && typeof b24 === 'object' && b24.error) {\n" +
	'  return [{\n' +
	'    json: {\n' +
	'      success: 0,\n' +
	'      error: String(b24.error),\n' +
	"      error_description: b24.error_description ? String(b24.error_description) : '',\n" +
	'    },\n' +
	'  }];\n' +
	'}\n' +
	"if (b24 && typeof b24 === 'object' && Object.prototype.hasOwnProperty.call(b24, 'result')) {\n" +
	'  return [{ json: { success: 1, result: b24.result } }];\n' +
	'}\n' +
	"return [{ json: { success: 0, error: 'unexpected_b24_shape', transport_response: b24 } }];";

const mapOk = node({
	type: 'n8n-nodes-base.code',
	version: 2,
	config: {
		name: 'Map Bitrix JSON → site response',
		parameters: {
			mode: 'runOnceForAllItems',
			language: 'javaScript',
			jsCode: mapOkJs,
		},
		position: [960, -140],
	},
	output: [{ json: { success: 1, result: {} } }],
});

const passErrJs =
	'const j = $input.first().json;\n' +
	"return [{ json: j.siteOut || { success: 0, error: 'prep_failed' } }];";

const passErr = node({
	type: 'n8n-nodes-base.code',
	version: 2,
	config: {
		name: 'Map prep error → site response',
		parameters: {
			mode: 'runOnceForAllItems',
			language: 'javaScript',
			jsCode: passErrJs,
		},
		position: [720, 140],
	},
	output: [{ json: { success: 0, error: 'unauthorized' } }],
});

const respond = node({
	type: 'n8n-nodes-base.respondToWebhook',
	version: 1.5,
	config: {
		name: 'Respond JSON',
		parameters: {
			respondWith: 'json',
			responseBody: expr('={{ $json }}'),
			options: {
				responseCode: 200,
			},
		},
		position: [1180, 0],
	},
});

sticky(
	'Сайт при регистрации вызывает этот вебхук **много раз** (каждый шаг — отдельный METHOD: crm.contact.add, crm.company.add и т.д.).\nУзел **POST Bitrix24 CRM REST** отправляет данные на портал; префикс вебхука в env **EKLEKTIKA_B24_REST_PREFIX**.',
	[prepareCode, postBitrix],
	{ color: 5 },
);

export default workflow('site-to-crm-rest-bridge', 'Site to CRM')
	.add(webhookTrigger)
	.to(
		prepareCode.to(
			gate.onTrue(postBitrix.to(mapOk.to(respond))).onFalse(passErr.to(respond)),
		),
	);
